<?php require 'bootstrap.php';admin_header('รายงานยอดขาย');?><p>นิยามยอดขาย: ยอดรวมรวมค่าจัดส่งเฉพาะคำสั่งซื้อที่จัดส่งสำเร็จ ตามวันที่สั่งซื้อ ไม่ใช่รายงานกระแสเงินสด สถานะได้รับเงิน COD แยกต่างหาก</p><?php foreach(['%Y-%m-%d'=>'รายวัน','%Y-%m'=>'รายเดือน'] as $format=>$label):?><h2>ยอดขาย<?=e(t($label))?></h2><table><tr><th>ช่วงเวลา</th><th>จำนวนคำสั่งซื้อส่งสำเร็จ</th><th>ยอดขาย</th></tr><?php foreach(q('SELECT DATE_FORMAT(created_at,?) period,COUNT(*) n,SUM(total) revenue FROM orders WHERE status="delivered" GROUP BY period ORDER BY period DESC LIMIT 60',[$format]) as $r):?><tr><td><?=e($r['period'])?></td><td><?=$r['n']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach ?></table><?php endforeach ?><h2>จำนวนคำสั่งซื้อทั้งหมด: <?=q('SELECT COUNT(*) FROM orders')->fetchColumn()?></h2><h2>สินค้าขายดี (จัดส่งสำเร็จ)</h2><?php foreach(q('SELECT i.product_id,MAX(i.name) name,SUM(i.quantity) qty,SUM(COALESCE(i.line_total,i.price*i.quantity)) revenue FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status="delivered" GROUP BY i.product_id ORDER BY qty DESC LIMIT 10') as $r):?><p><?=e($r['name'])?> · <?=$r['qty']?> ชิ้น · <?=money($r['revenue'])?></p><?php endforeach ?><h2>สินค้าใกล้หมด</h2><?php foreach(q('SELECT name,stock FROM products WHERE active=1 AND stock<=low_stock_threshold ORDER BY stock') as $r):?><p><?=e($r['name'])?> · <?=$r['stock']?> <?=e(t('ชิ้น'))?></p><?php endforeach;admin_footer();?>
